function SlotPickerSection({ zip }: { zip: string }) {
  return (
    <ErrorBoundary
      FallbackComponent={({ resetErrorBoundary }) => (
        <div role="status">
          <p>Couldn’t load delivery slots.</p>
          <button onClick={resetErrorBoundary}>Retry</button>
        </div>
      )}
    >
      <SlotPicker zip={zip} />
    </ErrorBoundary>
  );
}

function SlotPicker({ zip }: { zip: string }) {
  // throws synchronously if the response is malformed
  const slots = useSuspenseQuery(['slots', zip], () => fetchSlots(zip));
  return <SlotGrid slots={slots.data} />;
}
